// Ingest payload from Devyx website /api/chat
const body = $input.first().json.body || $input.first().json;

const sessionId = body.sessionId || `session_${Date.now()}`;
const userMessage = (body.message || '').trim();
const language = (body.language || 'darija').toLowerCase();
const currentPage = body.currentPage || '/';

// Detect if user is communicating in Darija (Arabic script, Arabizi, or language toggle)
const isExplicitDarija = language === 'darija' || language === 'ar-ma';
const arabiziPattern = /\b(bghit|khoya|kidayr|chhal|salam|fin|3afak|dyal|doka|dorka|lazem|saguem|khedma|wach|chno|fash|krite|tomobil|sachi|trisiti|bezzaf|kayen|chta|we9t|9bel|9alli|chouf|hada|hadi|mzyan|mli7|chwiya|3afak|t3ich)\b/i;
const arabicDarijaPattern = /(باش|ديال|بغيت|شنو|واش|شحال|فين|عافاك|زوين|بزاف|مزيان|دابا|كاين|كنديرو|كنقدرو|سوءال)/;

const isDarija = isExplicitDarija || arabiziPattern.test(userMessage) || arabicDarijaPattern.test(userMessage);

return {
  json: {
    sessionId,
    userMessage,
    language,
    currentPage,
    isDarija,
    // Context passed to Stage 1 Devyx Technical Assistant
    assistantInputText: userMessage
  }
};

